#include <iostream>
#include <string>
#include <cctype>
using namespace std;

int main() {
    int n;
    string s;
    cin >> n >> s;

    bool seen[26] = {};
    int count = 0;

    for (char ch : s) {
        int index = tolower(static_cast<unsigned char>(ch)) - 'a';
        if (index >= 0 && index < 26 && !seen[index]) {
            seen[index] = true;
            ++count;
        }
    }

    cout << (count == 26 ? "YES" : "NO");
    return 0;
}

